import subprocess, sys, json
out=[]; seen=set()
for t,pr,m,w,code,gis,rel,belt in G:
    assert t.lower() not in seen, t; seen.add(t.lower())
    res=""
    if code:
        p=subprocess.run([sys.executable,"-c",code],capture_output=True,text=True,timeout=20)
        assert p.returncode==0,(t,p.stderr)
        res=p.stdout.rstrip("\n")
    out.append(dict(term=t,pron=pr,meaning=m,why=w,code=code,out=res,gis=gis,related=rel,belt=belt))
json.dump(out,open("glossary.json","w"),ensure_ascii=False)
print(len(out),"terms;",sum(1 for o in out if o["code"]),"code examples verified with",sys.version.split()[0])
